package io.aetheris.orchestrator.trading;import jakarta.persistence.*;import java.time.*;@Entity @Table(name="aetheris_paper_accounts") public class PaperAccountEntity {@Id @Column(length=80) private String accountKey;private double startingBalance;private double cashBalance;private double dailyRealizedPnl;@Column(nullable=false,length=20) private String dayKey;@Column(nullable=false) private Instant updatedAt;protected PaperAccountEntity(){}public PaperAccountEntity(String key,double balance){this.accountKey=key;this.startingBalance=balance;this.cashBalance=balance;this.dayKey=LocalDate.now(ZoneOffset.UTC).toString();this.updatedAt=Instant.now();}public void ensureDay(){String today=LocalDate.now(ZoneOffset.UTC).toString();if(!today.equals(dayKey)){dayKey=today;dailyRealizedPnl=0;updatedAt=Instant.now();}}public void realize(double pnl){ensureDay();cashBalance+=pnl;dailyRealizedPnl+=pnl;updatedAt=Instant.now();}public String getAccountKey(){return accountKey;}public double getStartingBalance(){return startingBalance;}public double getCashBalance(){return cashBalance;}public double getDailyRealizedPnl(){return dailyRealizedPnl;}public String getDayKey(){return dayKey;}public Instant getUpdatedAt(){return updatedAt;}}
